import re
from collections import deque
from decimal import Decimal


class ExpressionCalculator:
    OPERATORS = {'+', '-', '*', '/', '(', ')', '%'}
    OPERATOR_PRIORITY = [0, 3, 2, 1, -1, 1, 0, 2]
    NEGATIVE_PRECEDING_CHARS = {'+', '-', '*', '/', '(', 'E', 'e'}

    def __init__(self):
        self.postfix_stack = deque()

    def calculate(self, expression):
        self.prepare(self.transform(expression))

        result_stack = deque()
        self.postfix_stack.reverse()

        while self.postfix_stack:
            current_op = self.extract_operand_or_operator()
            if not self.is_operator(current_op):
                result_stack.append(self.normalize_negative(current_op))
            else:
                second_value = self.normalize_negative(result_stack.pop())
                first_value = self.normalize_negative(result_stack.pop())
                result_stack.append(str(self._calculate(first_value, second_value, current_op)))

        return self._combine_result_stack(result_stack)

    def extract_operand_or_operator(self):
        current_op = self.postfix_stack.pop()
        return current_op

    @staticmethod
    def normalize_negative(value):
        return value.replace("~", "-")

    @staticmethod
    def _combine_result_stack(result_stack):
        return float(eval("*".join(result_stack)))

    def prepare(self, expression):
        op_stack = deque([','])
        arr = list(expression)
        current_index = 0
        count = self._process_expression_tokens(arr, op_stack, current_index, count)

        if (count > 1 or (count == 1 and not self.is_operator(arr[current_index]))):
            self.postfix_stack.append("".join(arr[current_index: current_index + count]))

        self._flush_remaining_operators(op_stack)

    def _process_expression_tokens(self, arr, op_stack, current_index, count):
        for i, current_op in enumerate(arr):
            if self.is_operator(current_op):
                if count > 0:
                    self.postfix_stack.append("".join(arr[current_index: current_index + count]))
                self._handle_operator_in_stack(current_op, op_stack, arr, i, count)
                count = 0
                current_index = i + 1
            else:
                count += 1
        return count

    def _handle_operator_in_stack(self, current_op, op_stack, arr, i, count):
        if current_op == ')':
            self._pop_until_open_paren(op_stack)
        else:
            self._pop_higher_or_equal_priority_ops(current_op, op_stack)
            op_stack.append(current_op)

    def _pop_until_open_paren(self, op_stack):
        while op_stack[-1] != '(':
            self.postfix_stack.append(str(op_stack.pop()))
        op_stack.pop()

    def _pop_higher_or_equal_priority_ops(self, current_op, op_stack):
        peek_op = op_stack[-1]
        while current_op != '(' and peek_op != ',' and self.compare(current_op, peek_op):
            self.postfix_stack.append(str(op_stack.pop()))
            peek_op = op_stack[-1]

    def _flush_remaining_operators(self, op_stack):
        while op_stack[-1] != ',':
            self.postfix_stack.append(str(op_stack.pop()))

    @classmethod
    def is_operator(cls, c):
        return c in cls.OPERATORS

    def compare(self, cur, peek):
        cur = self._normalize_operator_for_priority(cur)
        peek = self._normalize_operator_for_priority(peek)
        return self.OPERATOR_PRIORITY[ord(peek) - 40] >= self.OPERATOR_PRIORITY[ord(cur) - 40]

    @staticmethod
    def _normalize_operator_for_priority(op):
        return '/' if op == '%' else op

    @classmethod
    def _calculate(cls, first_value, second_value, current_op):
        if current_op == '+':
            return Decimal(first_value) + Decimal(second_value)
        elif current_op == '-':
            return Decimal(first_value) - Decimal(second_value)
        elif current_op == '*':
            return Decimal(first_value) * Decimal(second_value)
        elif current_op == '/':
            return Decimal(first_value) / Decimal(second_value)
        elif current_op == '%':
            return Decimal(first_value) % Decimal(second_value)
        else:
            raise ValueError("Unexpected operator: {}".format(current_op))

    @classmethod
    def transform(cls, expression):
        expression = re.sub(r"\s+", "", expression)
        expression = re.sub(r"=$", "", expression)
        arr = list(expression)

        cls._convert_negatives_to_tilde(arr)

        return cls._handle_leading_negative(arr)

    @classmethod
    def _convert_negatives_to_tilde(cls, arr):
        for i, c in enumerate(arr):
            if c == '-':
                if i == 0:
                    arr[i] = '~'
                else:
                    prev_c = arr[i - 1]
                    if prev_c in cls.NEGATIVE_PRECEDING_CHARS:
                        arr[i] = '~'

    @staticmethod
    def _handle_leading_negative(arr):
        if arr[0] == '~' and (len(arr) > 1 and arr[1] == '('):
            arr[0] = '-'
            return "0" + "".join(arr)
        else:
            return "".join(arr)
